using Microsoft.Maui.Controls.Shapes;
using Microsoft.Maui.Layouts;
using FoodExpiryApp.Models; using Microsoft.Maui.Controls; namespace FoodExpiryApp;
public class MainPage:ContentPage {
 readonly ProductRepository repo; readonly SearchBar search=new(){Placeholder="Поиск по названию, бренду или коду"}; readonly VerticalStackLayout cards=new(){Spacing=10}; int density=0; List<Product> all=new();
 public MainPage(ProductRepository r){repo=r;Title="Мои продукты";BackgroundColor=Color.FromArgb("#111116");var title=new Label{Text="Мои продукты",FontSize=28,FontAttributes=FontAttributes.Bold,TextColor=Colors.White};var densityBtn=new Button{Text="☷",WidthRequest=48,BackgroundColor=Color.FromArgb("#202027"),TextColor=Color.FromArgb("#A978F5")};densityBtn.Clicked+=(_,_)=>{density=(density+1)%3;Render();};var settings=new Button{Text="⚙",WidthRequest=48,BackgroundColor=Color.FromArgb("#202027"),TextColor=Color.FromArgb("#A978F5")};settings.Clicked+=async(_,_)=>await Navigation.PushAsync(new SettingsPage());search.TextChanged+=(_,_)=>Render();var add=new Button{Text="+ Добавить продукт",BackgroundColor=Color.FromArgb("#A978F5"),TextColor=Colors.Black};add.Clicked+=async(_,_)=>{await Navigation.PushAsync(new ProductEditPage(repo));};var info=new Button{Text="Инфо / поддержка",BackgroundColor=Color.FromArgb("#202027"),TextColor=Colors.White};info.Clicked+=async(_,_)=>await Navigation.PushAsync(new InfoPage());var top=new Grid{ColumnDefinitions={new ColumnDefinition(GridLength.Star),new ColumnDefinition(GridLength.Auto),new ColumnDefinition(GridLength.Auto)},ColumnSpacing=8};top.Add(title);top.Add(densityBtn,1);top.Add(settings,2);var actions=new Grid{ColumnDefinitions={new ColumnDefinition(GridLength.Star),new ColumnDefinition(GridLength.Star)},ColumnSpacing=8};actions.Add(add);actions.Add(info,1);Content=new ScrollView{Content=new VerticalStackLayout{Padding=18,Spacing=12,Children={top,search,actions,cards}}};}
 protected override async void OnAppearing(){base.OnAppearing();all=await repo.All();Render();}
 void Render(){if(cards==null)return;cards.Children.Clear();var q=search.Text?.Trim()??"";var filtered=all.Where(p=>string.IsNullOrEmpty(q)||p.Name.Contains(q,StringComparison.OrdinalIgnoreCase)||p.Brand.Contains(q,StringComparison.OrdinalIgnoreCase)||p.Barcode.Contains(q,StringComparison.OrdinalIgnoreCase)).ToList();foreach(var group in filtered.GroupBy(p=>p.GroupKey)){var items=group.OrderBy(p=>p.ExpiryDate).ToList();var p=items[0];string detail=string.Join(" • ",new[]{p.Variant,p.Volume,items.Count>1?$"{items.Count} шт.":""}.Where(s=>!string.IsNullOrWhiteSpace(s)));var info=new Label{Text=detail,TextColor=Color.FromArgb("#B7B2C1"),FontSize=density==0?14:density==1?12:10};var badges=new FlexLayout{Wrap=FlexWrap.Wrap,Direction=FlexDirection.Row};foreach(var item in items){var pill=new Border{BackgroundColor=ExpiryColor.For(item.ExpiryDate),StrokeThickness=0,StrokeShape=new RoundRectangle{CornerRadius=20},Padding=new Thickness(10,4),Margin=new Thickness(0,2,5,0),Content=new Label{Text=ExpiryColor.Label(item.ExpiryDate),TextColor=Color.FromArgb("#171717"),FontAttributes=FontAttributes.Bold,FontSize=12}};badges.Children.Add(pill);}var name=new Label{Text=p.Name,FontSize=density==0?20:density==1?17:14,FontAttributes=FontAttributes.Bold,TextColor=Colors.White};var glyph=new Label{Text=p.Category=="Молочные"?"🥛":p.Category=="Напитки"?"💧":p.Category=="Мясо и рыба"?"🥩":p.Category=="Овощи и фрукты"?"🥬":p.Category=="Заморозка"?"🧊":"📦",FontSize=density==2?18:32,VerticalOptions=LayoutOptions.Center};var body=new VerticalStackLayout{Spacing=4,Children={name}};if(density!=2)body.Children.Add(info);body.Children.Add(badges);var del=new Button{Text="×",TextColor=Color.FromArgb("#FF6878"),BackgroundColor=Colors.Transparent,WidthRequest=36};del.Clicked+=async(_,_)=>{var answer=items.Count>1?await DisplayActionSheet("Удалить товар","Отмена",null,"Один экземпляр","Все экземпляры"):"Один экземпляр";if(answer=="Один экземпляр")await repo.Delete(items[0]);else if(answer=="Все экземпляры")foreach(var x in items)await repo.Delete(x);all=await repo.All();Render();};var row=new Grid{ColumnDefinitions={new ColumnDefinition(GridLength.Auto),new ColumnDefinition(GridLength.Star),new ColumnDefinition(GridLength.Auto)},ColumnSpacing=10};row.Add(glyph);row.Add(body,1);row.Add(del,2);cards.Children.Add(new Border{BackgroundColor=CategoryStyle.Tint(p.Category),Stroke=Color.FromArgb("#3A3744"),StrokeThickness=1,StrokeShape=new RoundRectangle{CornerRadius=18},Padding=12,Content=row});} }
}
